function wholeMinutePairs(secs: number[]): number {
  let count = 0;
  for (let i = 0; i < secs.length; i++)
    for (let j = i + 1; j < secs.length; j++)
      if ((secs[i] + secs[j]) % 60 === 0) count++;
  return count;
}

