function wholeMinutePairs(secs: number[]): number {
  const seen = new Array(60).fill(0);
  let count = 0;
  for (const s of secs) {
    const r = s % 60;
    count += seen[(60 - r) % 60];
    seen[r]++;
  }
  return count;
}

